let observers=[],frames=new Set(),motionEpoch=0,statsCounted=false,scrollFrame=0,navSections=[];
const motionQuery=window.matchMedia('(prefers-reduced-motion: reduce)');
const motionAllowed=()=>!motionQuery.matches;
function clearMotion(){motionEpoch++;observers.forEach(o=>o.disconnect());observers=[];frames.forEach(cancelAnimationFrame);frames.clear()}
function restoreNumbers(){document.querySelectorAll('[data-number]').forEach(e=>{e.textContent=e.dataset.number;e.classList.remove('counting')})}
function setupMotion(){clearMotion();restoreNumbers();if(!motionAllowed())return;const hero=document.querySelector('.hero');hero.classList.add('hero-enter');hero.querySelectorAll('.eyebrow,h1,.intro,.hero-actions,.signature,.hero-art').forEach((e,i)=>e.style.setProperty('--enter-delay',(i*85)+'ms'))}
function animateAccordion(details){const summary=details.querySelector('summary');if(!summary)return;let animation=null;summary.addEventListener('click',event=>{if(!motionAllowed()||!details.animate)return;event.preventDefault();if(animation)return;const opening=!details.open;const from=details.getBoundingClientRect().height;if(opening)details.open=true;const styles=getComputedStyle(details);const border=parseFloat(styles.borderTopWidth||0)+parseFloat(styles.borderBottomWidth||0);const to=opening?details.getBoundingClientRect().height:summary.getBoundingClientRect().height+border;details.style.overflow='hidden';animation=details.animate({height:[from+'px',to+'px']},{duration:240,easing:'cubic-bezier(.22,1,.36,1)'});const cleanup=()=>{details.style.overflow='';animation=null};animation.onfinish=()=>{if(!opening)details.open=false;cleanup()};animation.oncancel=cleanup})}
function updateProgress(){const max=Math.max(0,document.documentElement.scrollHeight-innerHeight);const progress=document.querySelector('.progress');if(progress)progress.style.width=(max>0?Math.min(100,scrollY/max*100):0)+'%';const back=document.querySelector('.back-to-top');if(back)back.hidden=scrollY<Math.max(500,innerHeight*.7);let current='';navSections.forEach(e=>{if(e.getBoundingClientRect().top<=150)current=e.id});document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+current;a.classList.toggle('current',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}
function scheduleProgress(){if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;updateProgress()})}
function setMetadata(lang){document.documentElement.lang=lang}
function bind(lang){document.querySelectorAll('[data-lang]').forEach(button=>{button.classList.toggle('active',button.dataset.lang===lang);if(button.dataset.lang===lang)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});const header=document.querySelector('header'),menu=document.querySelector('.menu'),nav=document.querySelector('nav');function closeMenu(){nav.classList.remove('open');menu.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label',menu.dataset.openLabel)}menu.onclick=()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);menu.classList.toggle('is-open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?menu.dataset.closeLabel:menu.dataset.openLabel)};nav.querySelectorAll('a').forEach(a=>a.onclick=closeMenu);document.onkeydown=event=>{if(event.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}};document.onclick=event=>{if(nav.classList.contains('open')&&!header.contains(event.target))closeMenu()};document.querySelectorAll('details').forEach(animateAccordion);const back=document.querySelector('.back-to-top');if(back)back.onclick=event=>{event.preventDefault();window.scrollTo({top:0,behavior:motionAllowed()?'smooth':'auto'})};navSections=[...document.querySelectorAll('main section[id]')];setMetadata(lang);setupMotion(lang);updateProgress()}
function instantScroll(top){const root=document.documentElement;const previous=root.style.scrollBehavior;root.style.scrollBehavior='auto';window.scrollTo({top:Math.max(0,top),behavior:'auto'});root.style.scrollBehavior=previous}
bind(document.documentElement.lang);
if(location.hash){const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target)requestAnimationFrame(()=>target.scrollIntoView({block:'start',behavior:'auto'}))}
window.addEventListener('scroll',scheduleProgress,{passive:true});window.addEventListener('resize',scheduleProgress,{passive:true});
if(motionQuery.addEventListener)motionQuery.addEventListener('change',()=>setupMotion(document.documentElement.lang));else if(motionQuery.addListener)motionQuery.addListener(()=>setupMotion(document.documentElement.lang));
